async function getPageWithTotal(limit, offset) {
  const sql =
    "SELECT event_id, event_ts, event_type, user_id, count() OVER () AS _total " +
    "FROM analytics.events " +
    "ORDER BY event_ts ASC, event_id ASC " +
    `LIMIT ${limit} OFFSET ${offset} ` +
    "FORMAT JSONEachRow";
  const raw = await clickhousePost(sql);
  const lines = raw.split("\n").filter((l) => l.trim().length > 0);
  const rows = lines.map((line) => JSON.parse(line));
  let total = 0;
  if (rows.length > 0) {
    total = Number(rows[0]._total ?? 0);
  } else {
    const countRaw = await clickhousePost(
      "SELECT count() AS total FROM analytics.events FORMAT JSON",
    );
    const parsed = JSON.parse(countRaw);
    total = Number(parsed.data?.[0]?.total ?? 0);
  }
  const data = rows.map(({ _total, ...event }) => event);
  return { data, total };
}

